const {chromium}=require('C:/Temp/openclaw-playwright/node_modules/playwright');
(async()=>{const browser=await chromium.launch({channel:'chrome',headless:true});const page=await browser.newPage({viewport:{width:1440,height:1100}});try{await page.goto('http://localhost:9090/#/auth/login');await page.locator('#email').fill(process.env.DOCS_QA_EMAIL);await page.locator('#password').fill(process.env.DOCS_QA_PASSWORD);await page.getByRole('button',{name:'Login submit button'}).click();await page.waitForURL(u=>!u.hash.includes('/auth/login'));console.log('SIGNED_IN',page.url());console.log((await page.locator('body').innerText()).slice(0,7000));await page.context().storageState({path:'frontend/dist/docs-submit-review/qa-session.json'});}finally{await browser.close();}})().catch(e=>{console.error(e.message);process.exitCode=1});
